1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
31	// 时按损坏处理；已有台账文件无法读取、解析，存在两条配方编号与版本号
32	// 完全相同的配方记录，存在两条批次编号完全相同的批次记录，
33	// 任一配方版本的任一物料每份克数不是正数，
34	// 任一配方版本内同一物料编号出现多次，
35	// 任一批次绑定的配方版本未登记，
36	// 任一批次仍为草稿状态却带有投料记录，
37	// 已保存投料的物料编号不属于该批次绑定的配方版本，
38	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
39	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
40	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
41	func Open(dir string) (*Store, error) {
42		if dir == "" {
43			return nil, errors.New("数据位置不能为空")
44		}
45		if err := os.MkdirAll(dir, 0o755); err != nil {
46			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
47		}
48		info, err := os.Stat(dir)
49		if err != nil {
50			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
51		}
52		if !info.IsDir() {
53			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
54		}
55	
56		lockPath := filepath.Join(dir, lockFileName)
57		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
58		if err != nil {
59			return nil, fmt.Errorf("打开锁文件失败: %w", err)
60		}
61	
62		s := &Store{dir: dir, lockFile: lf}
63		if err := s.load(); err != nil {
64			lf.Close()
65			return nil, err
66		}
67		return s, nil
68	}
69	
70	// Close 释放台账占用的文件锁。
71	func (s *Store) Close() error {
72		s.mu.Lock()
73		defer s.mu.Unlock()
74		if s.lockFile == nil {
75			return nil
76		}
77		err := s.lockFile.Close()
78		s.lockFile = nil
79		return err
80	}
81	
82	func (s *Store) lockExclusive() error {
83		if s.lockFile == nil {
84			return errors.New("台账已关闭")
85		}
86		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
87			return fmt.Errorf("锁定台账失败: %w", err)
88		}
89		return nil
90	}
91	
92	func (s *Store) lockShared() error {
93		if s.lockFile == nil {
94			return errors.New("台账已关闭")
95		}
96		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
97			return fmt.Errorf("锁定台账失败: %w", err)
98		}
99		return nil
100	}
101	
102	func (s *Store) unlock() {
103		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
104	}
105	
106	func (s *Store) load() error {
107		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
108		if err != nil {
109			if os.IsNotExist(err) {
110				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
111				return nil
112			}
113			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
114		}
115		if len(data) == 0 {
116			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
117			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
118			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
119			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
120		}
121		var st persistedState
122		if err := json.Unmarshal(data, &st); err != nil {
123			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
124		}
125		if st.Version != stateVersion {
126			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
127		}
128		if err := validateState(&st); err != nil {
129			return err
130		}
131		if st.Requests == nil {
132			st.Requests = map[string]*requestRecord{}
133		}
134		s.state = &st
135		return nil
136	}
137	
138	// validateState 检查台账的引用完整性与数量合法性：
139	//   - 配方由配方编号与版本号共同识别，同一台账内每组编号+版本号只能
140	//     对应一条配方记录。只要同组出现第二条记录，无论名称、物料、每份克数
141	//     是否相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或
142	//     最后一条、不能合并物料、也不能自行删除一条后继续——重复记录会让
143	//     查询结果与批次的应投依据取决于文件中的排列顺序。重复版本即使尚未
144	//     被任何批次引用也一样拒绝，其他配方与批次完整也不能放行本次读取。
145	//   - 批次由批次编号唯一识别，同一台账内一个编号只能对应一条批次记录。
146	//     同一编号出现第二条记录，无论绑定的配方版本、计划份数、状态是否
147	//     相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或最后
148	//     一条、不能合并投料、不能自动改号或删除一条后继续——重复记录会让
149	//     同一编号查到的配方、投料与数量核对取决于文件中的排列顺序。其他
150	//     批次完整、投料数量吻合，或调用方只想查看另一个正常批次，都不能
151	//     放行本次读取；不同编号的批次绑定同一配方版本不受影响。
152	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
153	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
154	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
155	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
156	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
157	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
158	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
159	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
160	//     不同版本、不同配方各自使用同一物料编号不受影响。
161	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
162	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
163	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
164	//   - 草稿批次不能带有任何投料记录：登记投料只允许操作执行中的批次，
165	//     草稿尚未开始执行，出现投料说明保存内容自相矛盾。任一草稿批次包含
166	//     至少一条投料，整份台账即视为损坏——即使这些投料的物料都属于绑定
167	//     版本、克数均为合法正数、累计实投恰好等于应投，也不能接受；不能
168	//     丢弃投料后当作干净草稿，不能把批次自动改为执行中或已关闭，也不
169	//     能替调用方改选配方版本来继续读取。台账里另有正常批次、调用方只
170	//     查询其他配方或批次，都不能绕过这项矛盾。没有投料的草稿不受影响；
171	//     执行中尚未投料、已关闭批次没有投料或仍有欠投超投都属正常。
172	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
173	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
174	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
175	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
176	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
177	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
178	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
179	func validateState(st *persistedState) error {
180		// 先按“配方编号 + 版本号”唯一标识遍历全部配方记录：同组出现第二条
181		// 记录即数据损坏，必须先于一切按标识查找的校验拒绝——否则重复记录
182		// 会让 findRecipe 总是返回排在前面的一条，查询结果与批次应投依据都
183		// 取决于文件排列顺序。完全相同的内容也不是合法重复。
184		versions := make(map[recipeKey]bool, len(st.Recipes))
185		for _, r := range st.Recipes {
186			if r == nil {
187				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
188			}
189			key := recipeKey{r.RecipeNo, r.Version}
190			if versions[key] {
191				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方记录重复",
192					ErrCorruptData, r.RecipeNo, r.Version)
193			}
194			versions[key] = true
195		}
196		for _, r := range st.Recipes {
197			seen := make(map[string]bool, len(r.Materials))
198			for _, m := range r.Materials {
199				if seen[m.MaterialNo] {
200					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
201						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
202				}
203				seen[m.MaterialNo] = true
204				if m.GramsMilli <= 0 {
205					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
206						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
207				}
208			}
209		}
210		// 再按批次编号唯一标识遍历全部批次记录：同一编号出现第二条记录即数据
211		// 损坏，必须先于一切按编号查找的校验拒绝——否则 findBatch 总是返回排在
212		// 前面的一条，同一编号查到的配方、投料与数量核对都取决于文件排列顺序。
213		// 两条记录即使绑定不同配方版本、计划份数不同或状态不同也属于重复；
214		// 内容完全一致同样不是合法记录。不能挑第一条或最后一条、不能合并投料、
215		// 也不能自动改号或删除一条后继续。不同批次绑定同一配方版本不受影响。
216		batchNos := make(map[string]bool, len(st.Batches))
217		for _, b := range st.Batches {
218			if b == nil {
219				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
220			}
221			if batchNos[b.BatchNo] {
222				return fmt.Errorf("%w: 批次编号 %q 的批次记录重复", ErrCorruptData, b.BatchNo)
223			}
224			batchNos[b.BatchNo] = true
225		}
226		for _, b := range st.Batches {
227			// 草稿尚未开始执行，不能登记投料；已保存的草稿却带着投料，
228			// 说明记录自相矛盾。必须先于配方归属与数量校验拒绝——否则
229			// 这份草稿还能被打开、调整份数或改选配方版本，留下按旧计划
230			// 登记的投料。不能丢弃投料当作干净草稿，不能自动改状态，也
231			// 不能改选版本后继续。
232			if b.Status == StatusDraft && len(b.Feedings) > 0 {
233				return fmt.Errorf("%w: 批次 %q 仍为草稿状态，却存在 %d 条投料记录",
234					ErrCorruptData, b.BatchNo, len(b.Feedings))
235			}
236			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
237			if r == nil {
238				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
239					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
240			}
241			if err := validateFeedings(b, r); err != nil {
242				return err
243			}
244		}
245		return nil
246	}
247	
248	// validateFeedings 检查一个批次内已保存投料的合法性与配方归属。
249	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
250	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
251	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
252	// 在此拒绝。
253	func validateFeedings(b *batchRecord, r *recipeRecord) error {
254		acc := newFeedingAccumulator()
255		for _, f := range b.Feedings {
256			belongs := false
257			for _, m := range r.Materials {
258				if m.MaterialNo == f.MaterialNo {
259					belongs = true
260					break
261				}
262			}
263			if !belongs {
264				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
265					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
266			}
267			if f.GramsMilli <= 0 {
268				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
269					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
270			}
271			if !acc.add(f.MaterialNo, f.GramsMilli) {
272				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
273					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
274			}
275		}
276		return nil
277	}
278	
279	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
280	func (s *Store) persist(st *persistedState) error {
281		data, err := json.MarshalIndent(st, "", "  ")
282		if err != nil {
283			return err
284		}
285		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
286		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
287		if err != nil {
288			return err
289		}
290		if _, err := f.Write(data); err != nil {
291			f.Close()
292			return err
293		}
294		if err := f.Sync(); err != nil {
295			f.Close()
296			return err
297		}
298		if err := f.Close(); err != nil {
299			return err
300		}
301		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
302			return err
303		}
304		if d, err := os.Open(s.dir); err == nil {
305			_ = d.Sync()
306			_ = d.Close()
307		}
308		return nil
309	}
310	
311	func cloneState(st *persistedState) (*persistedState, error) {
312		data, err := json.Marshal(st)
313		if err != nil {
314			return nil, err
315		}
316		var out persistedState
317		if err := json.Unmarshal(data, &out); err != nil {
318			return nil, err
319		}
320		if out.Requests == nil {
321			out.Requests = map[string]*requestRecord{}
322		}
323		return &out, nil
324	}
325	
326	// write 是所有写入操作的统一入口：
327	//   - reqNo 为空直接报错；
328	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
329	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
330	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
331	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
332	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
333		if reqNo == "" {
334			return errors.New("请求编号不能为空")
335		}
336		s.mu.Lock()
337		defer s.mu.Unlock()
338		if err := s.lockExclusive(); err != nil {
339			return err
340		}
341		defer s.unlock()
342	
343		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
344		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
345		if err := s.load(); err != nil {
346			return err
347		}
348	
349		payloadRaw, err := json.Marshal(payload)
350		if err != nil {
351			return err
352		}
353		payloadStr := string(payloadRaw)
354	
355		if req, ok := s.state.Requests[reqNo]; ok {
356			if req.Op != op || req.Payload != payloadStr {
357				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
358					ErrRequestConflict, reqNo, req.Op, op)
359			}
360			if err := json.Unmarshal(req.Result, out); err != nil {
361				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
362			}
363			return nil
364		}
365	
366		clone, err := cloneState(s.state)
367		if err != nil {
368			return err
369		}
370		result, err := apply(clone)
371		if err != nil {
372			return err
373		}
374		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
375		if err := s.persist(clone); err != nil {
376			return fmt.Errorf("保存台账失败: %w", err)
377		}
378		s.state = clone
379		if err := json.Unmarshal(result, out); err != nil {
380			return fmt.Errorf("解析请求结果失败: %w", err)
381		}
382		return nil
383	}
384	
385	// read 在共享锁下读取当前状态。
386	func (s *Store) read(fn func(*persistedState) error) error {
387		s.mu.Lock()
388		defer s.mu.Unlock()
389		if err := s.lockShared(); err != nil {
390			return err
391		}
392		defer s.unlock()
393		if err := s.load(); err != nil {
394			return err
395		}
396		return fn(s.state)
397	}
398	
399	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
400	
401	func buildRecipeView(r *recipeRecord) *RecipeView {
402		mats := make([]MaterialView, 0, len(r.Materials))
403		for _, m := range r.Materials {
404			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
405		}
406		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
407	}
408	
409	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
410		v := &BatchView{
411			BatchNo:         b.BatchNo,
412			RecipeNo:        r.RecipeNo,
413			RecipeVersion:   r.Version,
414			RecipeName:      r.Name,
415			PlannedPortions: b.PlannedPortions,
416			Status:          b.Status,
417			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
418			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
419		}
420	
421		for _, f := range b.Feedings {
422			v.Feedings = append(v.Feedings, FeedingView{
423				Seq:        f.Seq,
424				MaterialNo: f.MaterialNo,
425				Grams:      f.GramsMilli.String(),
426				Time:       f.Time,
427				Registrar:  f.Registrar,
428			})
429		}
430	
431		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
432		// 这里仍用同一套累计规则防一手整数回绕。
433		acc := newFeedingAccumulator()
434		for _, f := range b.Feedings {
435			if !acc.add(f.MaterialNo, f.GramsMilli) {
436				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
437					ErrCorruptData, b.BatchNo, f.MaterialNo)
438			}
439		}
440	
441		// 数量核对按配方物料逐项列出；台账在读取时已通过 validateState 校验，
442		// 这里仍防一手同一版本内物料编号重复，避免返回重复的数量核对项。
443		seen := make(map[string]bool, len(r.Materials))
444		for _, m := range r.Materials {
445			if seen[m.MaterialNo] {
446				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
447					ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
448			}
449			seen[m.MaterialNo] = true
450			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
451			if err != nil {
452				return nil, fmt.Errorf("批次 %q 数量核对失败: %w", b.BatchNo, err)
453			}
454			act := acc.total(m.MaterialNo)
455			v.Materials = append(v.Materials, MaterialRequirement{
456				MaterialNo:      m.MaterialNo,
457				RequiredGrams:   required.String(),
458				ActualGrams:     act.String(),
459				DifferenceGrams: (act - required).String(),
460			})
461		}
462		return v, nil
463	}
464	
465	// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
466	type recipeKey struct {
467		recipeNo string
468		version  string
469	}
470	
471	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
472		for _, r := range st.Recipes {
473			if r.RecipeNo == recipeNo && r.Version == version {
474				return r
475			}
476		}
477		return nil
478	}
479	
480	func findBatch(st *persistedState, batchNo string) *batchRecord {
481		for _, b := range st.Batches {
482			if b.BatchNo == batchNo {
483				return b
484			}
485		}
486		return nil
487	}
488

