13	)
14	
15	// 手工构造一份含指定投料记录的台账文件。
16	func writeFeedingState(t *testing.T, dir string, feedings []feedingRecord) []byte {
17		t.Helper()
18		return writeStateFile(t, dir, &persistedState{
19			Version: stateVersion,
20			Recipes: []*recipeRecord{recipeR1v1()},
21			Batches: []*batchRecord{{
22				BatchNo:         "B1",
23				RecipeNo:        "R1",
24				RecipeVersion:   "v1",
25				PlannedPortions: 2,
26				Status:          StatusExecuting,
27				Feedings:        feedings,
28			}},
29		})
30	}
31	
32	// 已保存的投料为零或负数时，Open 必须返回 ErrCorruptData：
33	// 错误信息指出批次编号、物料编号与登记序号，并与累计超限的原因区分开；
34	// 不返回可用的台账对象，也不改写原文件。
35	func TestOpenRejectsNonPositiveFeeding(t *testing.T) {
36		cases := []struct {
37			name  string
38			grams gramsMilli
39		}{
40			{"零", 0},
41			{"负数", -500},
42		}
43		for _, tc := range cases {
44			t.Run(tc.name, func(t *testing.T) {
45				dir := t.TempDir()
46				original := writeFeedingState(t, dir, []feedingRecord{
47					{Seq: 1, MaterialNo: "M1", GramsMilli: 1000, Time: time.Now(), Registrar: "张三"},
48					{Seq: 2, MaterialNo: "M1", GramsMilli: tc.grams, Time: time.Now(), Registrar: "张三"},
49				})
50	
51				s, err := Open(dir)
52				if !errors.Is(err, ErrCorruptData) {
53					t.Fatalf("投料数量不是正数应返回 ErrCorruptData，得到 %v", err)
54				}
55				if s != nil {
56					s.Close()
57					t.Fatalf("损坏台账不应返回可用的 Store 对象")
58				}
59				msg := err.Error()
60				for _, want := range []string{"B1", "M1", "2"} {
61					if !strings.Contains(msg, want) {
62						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
63					}
64				}
65				if !strings.Contains(msg, "不是正数") {
66					t.Fatalf("错误信息应区分单条数量非法，得到 %v", err)
67				}
68				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
69				if err != nil {
70					t.Fatal(err)
71				}
72				if !bytes.Equal(got, original) {
73					t.Fatalf("拒绝打开不应改动台账文件")
74				}
75			})
76		}
77	}
78	
79	// 负数记录即使与正数相加后落在范围内，也不能被接受。
80	func TestOpenRejectsNegativeFeedingEvenWhenNetted(t *testing.T) {
81		dir := t.TempDir()
82		writeFeedingState(t, dir, []feedingRecord{
83			{Seq: 1, MaterialNo: "M1", GramsMilli: 1000, Time: time.Now(), Registrar: "张三"},
84			{Seq: 2, MaterialNo: "M1", GramsMilli: -400, Time: time.Now(), Registrar: "张三"},
85		})
86		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
87			t.Fatalf("正负相抵后落在范围内仍应拒绝，得到 %v", err)
88		}
89	}
90	
91	// 同一批次同一物料累计实投超过上限时，Open 必须返回 ErrCorruptData：
92	// 错误信息指出批次编号与物料编号，并与单条非正数的原因区分开。
93	func TestOpenRejectsCumulativeOverLimit(t *testing.T) {
94		dir := t.TempDir()
95		writeFeedingState(t, dir, []feedingRecord{
96			{Seq: 1, MaterialNo: "M1", GramsMilli: gramsMilli(math.MaxInt64), Time: time.Now(), Registrar: "张三"},
97			{Seq: 2, MaterialNo: "M1", GramsMilli: 1, Time: time.Now(), Registrar: "张三"},
98		})
99		s, err := Open(dir)
100		if !errors.Is(err, ErrCorruptData) {
101			t.Fatalf("累计超限应返回 ErrCorruptData，得到 %v", err)
102		}
103		if s != nil {
104			s.Close()
105			t.Fatalf("损坏台账不应返回可用的 Store 对象")
106		}
107		msg := err.Error()
108		for _, want := range []string{"B1", "M1"} {
109			if !strings.Contains(msg, want) {
110				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
111			}
112		}
113		if !strings.Contains(msg, "超出上限") {
114			t.Fatalf("错误信息应区分累计超限，得到 %v", err)
115		}
116	}
117	
118	// 累计恰好等于上限合法；上限按批次内物料分别判断，
119	// 两种物料各自达到上限不因合计更大而被拒绝。
120	func TestOpenAcceptsLimitExactlyAndPerMaterial(t *testing.T) {
121		dir := t.TempDir()
122		writeStateFile(t, dir, &persistedState{
123			Version: stateVersion,
124			Recipes: []*recipeRecord{{
125				RecipeNo: "R1", Version: "v1", Name: "配方一",
126				Materials: []materialRecord{
127					{MaterialNo: "M1", GramsMilli: 100000},
128					{MaterialNo: "M2", GramsMilli: 500},
129				},
130			}},
131			Batches: []*batchRecord{{
132				BatchNo: "B1", RecipeNo: "R1", RecipeVersion: "v1",
133				PlannedPortions: 2, Status: StatusExecuting,
134				Feedings: []feedingRecord{
135					{Seq: 1, MaterialNo: "M1", GramsMilli: gramsMilli(math.MaxInt64), Time: time.Now(), Registrar: "张三"},
136					{Seq: 2, MaterialNo: "M2", GramsMilli: gramsMilli(math.MaxInt64), Time: time.Now(), Registrar: "李四"},
137				},
138			}},
139		})
140		s, err := Open(dir)
141		if err != nil {
142			t.Fatalf("各自恰好达到上限应正常打开: %v", err)
143		}
144		defer s.Close()
145		view, err := s.GetBatch("B1")
146		if err != nil {
147			t.Fatal(err)
148		}
149		got := map[string]string{}
150		for _, m := range view.Materials {
151			got[m.MaterialNo] = m.ActualGrams
152		}
153		if got["M1"] != limitGrams || got["M2"] != limitGrams {
154			t.Fatalf("累计实投应各自等于上限，得到 %v", got)
155		}
156	}
157	
158	// 台账打开后保存内容变成投料数量非法：下一次查询或写入同样失败，
159	// 不能沿用此前正常的内容；查询或修改正常批次也不能绕过；
160	// 被拒绝的写入不保存业务变更、不占用请求编号，原台账内容不变。
161	func TestFeedingCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
162		dir := t.TempDir()
163		s, err := Open(dir)
164		if err != nil {
165			t.Fatal(err)
166		}
167		defer s.Close()
168	
169		if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
170			{MaterialNo: "M1", Grams: "100"},
171		}); err != nil {
172			t.Fatal(err)
173		}
174		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
175			t.Fatal(err)
176		}
177		if _, err := s.StartBatch("s1", "B1"); err != nil {
178			t.Fatal(err)
179		}
180		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 5); err != nil {
181			t.Fatal(err)
182		}
183		if _, err := s.StartBatch("s2", "B2"); err != nil {
184			t.Fatal(err)
185		}
186		fixedTime := time.Date(2026, 8, 1, 9, 0, 0, 0, time.UTC)
187		if _, err := s.AddFeeding("feed-ok", "B2", "M1", "5", fixedTime, "张三"); err != nil {
188			t.Fatal(err)
189		}
190	
191		// 把 B1 的保存内容改坏：加入一条负数投料（B2 仍完整）。
192		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
193		if err != nil {
194			t.Fatal(err)
195		}
196		var broken persistedState
197		if err := json.Unmarshal(good, &broken); err != nil {
198			t.Fatal(err)
199		}
200		for _, b := range broken.Batches {
201			if b.BatchNo == "B1" {
202				b.Feedings = append(b.Feedings, feedingRecord{
203					Seq: 1, MaterialNo: "M1", GramsMilli: -1, Time: fixedTime, Registrar: "张三",
204				})
205			}
206		}
207		badBytes := writeStateFile(t, dir, &broken)
208	
209		// 查询损坏批次与正常批次都必须失败。
210		for _, batchNo := range []string{"B1", "B2"} {
211			if _, err := s.GetBatch(batchNo); !errors.Is(err, ErrCorruptData) {
212				t.Fatalf("查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
213			}
214		}
215		// 写入正常批次同样不能绕过。
216		if _, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "李四"); !errors.Is(err, ErrCorruptData) {
217			t.Fatalf("损坏台账上投料应返回 ErrCorruptData，得到 %v", err)
218		}
219	
220		// 被拒绝的写入不改动文件、不占用请求编号。
221		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
222		if err != nil {
223			t.Fatal(err)
224		}
225		if !bytes.Equal(after, badBytes) {
226			t.Fatalf("被拒绝的写入不应改动台账文件")
227		}
228		if bytes.Contains(after, []byte("feed-rejected")) {
229			t.Fatalf("被拒绝的写入不应留下请求记录")
230		}
231	
232		// 恢复后原记录完整可用，被拒绝过的请求编号仍可合法提交。
233		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
234			t.Fatal(err)
235		}
236		b2, err := s.GetBatch("B2")
237		if err != nil {
238			t.Fatalf("恢复后查询应成功: %v", err)
239		}
240		if len(b2.Feedings) != 1 || b2.Feedings[0].Grams != "5" {
241			t.Fatalf("原有投料记录应保留: %+v", b2)
242		}
243		f, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "李四")
244		if err != nil {
245			t.Fatalf("被拒绝的请求编号应仍可合法使用: %v", err)
246		}
247		if f.Seq != 2 || f.Grams != "1" {
248			t.Fatalf("新投料结果不正确: %+v", f)
249		}
250	}
