1	package release
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	// 组合调整的两版配方：
9	//   - R1/v1：M1=100、M2=0.5、M3=0.010（M2 仅在 v1 中）
10	//   - R1/v2：M1=250（同一物料每份克数不同）、M4=2（M4 是新版本新增物料）
11	func registerTwoRecipeVersions(t *testing.T, s *Store) {
12		t.Helper()
13		if _, err := s.RegisterRecipe("recipe-v1", "R1", "v1", "配方初版", []MaterialInput{
14			{MaterialNo: "M1", Grams: "100"},
15			{MaterialNo: "M2", Grams: "0.5"},
16			{MaterialNo: "M3", Grams: "0.010"},
17		}); err != nil {
18			t.Fatalf("登记 R1/v1 失败: %v", err)
19		}
20		if _, err := s.RegisterRecipe("recipe-v2", "R1", "v2", "配方改版", []MaterialInput{
21			{MaterialNo: "M1", Grams: "250"},
22			{MaterialNo: "M4", Grams: "2"},
23		}); err != nil {
24			t.Fatalf("登记 R1/v2 失败: %v", err)
25		}
26	}
27	
28	func materialsMap(v *BatchView) map[string]MaterialRequirement {
29		m := make(map[string]MaterialRequirement, len(v.Materials))
30		for _, item := range v.Materials {
31			m[item.MaterialNo] = item
32		}
33		return m
34	}
35	
36	func checkRequirement(t *testing.T, got map[string]MaterialRequirement, mat, req, act, diff string) {
37		t.Helper()
38		m, ok := got[mat]
39		if !ok {
40			t.Fatalf("数量核对缺少物料 %q，实际有 %+v", mat, got)
41		}
42		if m.RequiredGrams != req || m.ActualGrams != act || m.DifferenceGrams != diff {
43			t.Fatalf("物料 %q 核对应为 应投=%s 实投=%s 差额=%s，得到 应投=%s 实投=%s 差额=%s",
44				mat, req, act, diff, m.RequiredGrams, m.ActualGrams, m.DifferenceGrams)
45		}
46	}
47	
48	// 一次提交同时调整配方版本与计划份数：两项调整一起生效。
49	// 数量核对必须完全采用新版本的每份克数与新份数：
50	//   - 同一物料 M1 在两个版本中每份克数不同（100 → 250），按新值计算；
51	//   - 新版本没有的旧物料 M2、M3 不残留；
52	//   - 新版本新增的 M4 即使从未投料也必须列出；
53	//   - 草稿累计实投为零，差额为应投量的负值；
54	//   - 批次编号不变，状态仍为草稿，返回结果与随后查询指向同一新结果。
55	func TestUpdateDraftRecipeAndPortionsAtomicSuccess(t *testing.T) {
56		s := openTestStore(t)
57		registerTwoRecipeVersions(t, s)
58		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
59			t.Fatalf("创建批次失败: %v", err)
60		}
61	
62		// 调整前先记录原始数量核对，失败时用于比对回滚。
63		before, err := s.GetBatch("B1")
64		if err != nil {
65			t.Fatal(err)
66		}
67		beforeMats := materialsMap(before)
68	
69		view, err := s.UpdateDraftBatch("u-combo", "B1", "R1", "v2", 3)
70		if err != nil {
71			t.Fatalf("同时改配方与份数应成功: %v", err)
72		}
73	
74		// 返回结果指向新版本、新份数，批次编号与状态不变。
75		if view.BatchNo != "B1" {
76			t.Fatalf("批次编号不应改变，得到 %q", view.BatchNo)
77		}
78		if view.RecipeNo != "R1" || view.RecipeVersion != "v2" || view.RecipeName != "配方改版" {
79			t.Fatalf("应指向新配方版本 R1/v2，得到 %q %q %q", view.RecipeNo, view.RecipeVersion, view.RecipeName)
80		}
81		if view.PlannedPortions != 3 {
82			t.Fatalf("计划份数应为 3，得到 %d", view.PlannedPortions)
83		}
84		if view.Status != StatusDraft {
85			t.Fatalf("调整后仍应为草稿，得到 %s", view.Status)
86		}
87		if len(view.Feedings) != 0 {
88			t.Fatalf("草稿不应有投料，得到 %d 条", len(view.Feedings))
89		}
90	
91		// 数量核对完全按新版本物料 × 新份数：
92		// M1 = 250 × 3 = 750（不是旧的 100 × 3 或 250 × 10）；M4 = 2 × 3 = 6。
93		got := materialsMap(view)
94		if len(got) != 2 {
95			t.Fatalf("新版本只有 M1、M4 两种物料，得到 %d 项: %+v", len(got), view.Materials)
96		}
97		checkRequirement(t, got, "M1", "750", "0", "-750")
98		checkRequirement(t, got, "M4", "6", "0", "-6")
99		if _, leftover := got["M2"]; leftover {
100			t.Fatalf("新版本没有的旧物料 M2 不应残留: %+v", got["M2"])
101		}
102		if _, leftover := got["M3"]; leftover {
103			t.Fatalf("新版本没有的旧物料 M3 不应残留: %+v", got["M3"])
104		}
105	
106		// 随后查询与返回结果一致。
107		again, err := s.GetBatch("B1")
108		if err != nil {
109			t.Fatalf("调整后查询失败: %v", err)
110		}
111		if again.BatchNo != "B1" || again.RecipeNo != "R1" || again.RecipeVersion != "v2" ||
112			again.PlannedPortions != 3 || again.Status != StatusDraft {
113			t.Fatalf("查询结果与调整返回不一致: %+v", again)
114		}
115		againMats := materialsMap(again)
116		if len(againMats) != 2 {
117			t.Fatalf("查询应只含新版本两种物料，得到 %d 项", len(againMats))
118		}
119		checkRequirement(t, againMats, "M1", "750", "0", "-750")
120		checkRequirement(t, againMats, "M4", "6", "0", "-6")
121	
122		// 两个已登记的配方版本本身都不能被这次调整改写。
123		r1, err := s.GetRecipe("R1", "v1")
124		if err != nil {
125			t.Fatalf("查询 R1/v1 失败: %v", err)
126		}
127		if r1.Name != "配方初版" || len(r1.Materials) != 3 {
128			t.Fatalf("R1/v1 被调整改写: %+v", r1)
129		}
130		r1m := map[string]string{}
131		for _, m := range r1.Materials {
132			r1m[m.MaterialNo] = m.Grams
133		}
134		if r1m["M1"] != "100" || r1m["M2"] != "0.5" || r1m["M3"] != "0.01" {
135			t.Fatalf("R1/v1 物料被改写: %+v", r1m)
136		}
137		r2, err := s.GetRecipe("R1", "v2")
138		if err != nil {
139			t.Fatalf("查询 R1/v2 失败: %v", err)
140		}
141		if r2.Name != "配方改版" || len(r2.Materials) != 2 {
142			t.Fatalf("R1/v2 不应被改写: %+v", r2)
143		}
144		r2m := map[string]string{}
145		for _, m := range r2.Materials {
146			r2m[m.MaterialNo] = m.Grams
147		}
148		if r2m["M1"] != "250" || r2m["M4"] != "2" {
149			t.Fatalf("R1/v2 物料被改写: %+v", r2m)
150		}
151	
152		// 防止以后误把 before 优化掉：确认调整前核对确实不同。
153		checkRequirement(t, beforeMats, "M1", "1000", "0", "-1000")
154	}
155	
156	// 份数有效但选中的配方版本不存在：返回 ErrNotFound，
157	// 整批保留调整前的完整结果——原份数、原配方、原有数量核对一项都不能变。
158	func TestUpdateDraftComboMissingRecipeKeepsWholeBatch(t *testing.T) {
159		s := openTestStore(t)
160		registerTwoRecipeVersions(t, s)
161		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
162			t.Fatal(err)
163		}
164	
165		_, err := s.UpdateDraftBatch("u-missing", "B1", "R1", "v9", 5)
166		if !errors.Is(err, ErrNotFound) {
167			t.Fatalf("不存在的配方版本应返回 ErrNotFound，得到 %v", err)
168		}
169	
170		got, err := s.GetBatch("B1")
171		if err != nil {
172			t.Fatalf("失败后查询批次失败: %v", err)
173		}
174		if got.BatchNo != "B1" || got.RecipeNo != "R1" || got.RecipeVersion != "v1" ||
175			got.PlannedPortions != 10 || got.Status != StatusDraft {
176			t.Fatalf("失败后应保留原批次（R1/v1、10 份、草稿），得到 %+v", got)
177		}
178		// 原数量核对仍完整：M1=100×10、M2=0.5×10、M3=0.010×10，三项都在。
179		mats := materialsMap(got)
180		if len(mats) != 3 {
181			t.Fatalf("应保留原配方的全部 3 种物料，得到 %d 项: %+v", len(mats), mats)
182		}
183		checkRequirement(t, mats, "M1", "1000", "0", "-1000")
184		checkRequirement(t, mats, "M2", "5", "0", "-5")
185		checkRequirement(t, mats, "M3", "0.1", "0", "-0.1")
186	}
187	
188	// 目标版本存在，但按新份数计算后某物料应投量超出可表示范围：
189	// 操作必须整体失败，不能留下已改好的份数或配方，不能出现整数回绕后的数量，
190	// 也不能只保留部分物料。判定按物料分别进行，不与其他物料相加。
191	func TestUpdateDraftComboRequiredOverflowRejectedAtomically(t *testing.T) {
192		s := openTestStore(t)
193		// v-ov：每份需要恰好上限 9223372036854775.807 克，另有一物料 M2。
194		if _, err := s.RegisterRecipe("recipe-ov", "R9", "v1", "上限配方", []MaterialInput{
195			{MaterialNo: "Mbig", Grams: "9223372036854775.807"},
196			{MaterialNo: "M2", Grams: "1"},
197		}); err != nil {
198			t.Fatalf("登记上限配方失败: %v", err)
199		}
200		if _, err := s.RegisterRecipe("recipe-base", "R1", "v1", "基础配方", []MaterialInput{
201			{MaterialNo: "M1", Grams: "100"},
202		}); err != nil {
203			t.Fatalf("登记基础配方失败: %v", err)
204		}
205		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
206			t.Fatalf("创建批次失败: %v", err)
207		}
208	
209		// 一份可以计算（恰好上限）：切版本同时改为 1 份应成功。
210		one, err := s.UpdateDraftBatch("u-one", "B1", "R9", "v1", 1)
211		if err != nil {
212			t.Fatalf("应投恰好等于上限的一份应可计算: %v", err)
213		}
214		oneMats := materialsMap(one)
215		checkRequirement(t, oneMats, "Mbig", "9223372036854775.807", "0", "-9223372036854775.807")
216		checkRequirement(t, oneMats, "M2", "1", "0", "-1")
217	
218		// 同一提交再改为两份：Mbig 应投 = 上限 × 2 溢出，必须拒绝，
219		// 不能把 Mbig 与 M2 的数量相加后再判断。
220		_, err = s.UpdateDraftBatch("u-two", "B1", "R9", "v1", 2)
221		if err == nil {
222			t.Fatal("应投量溢出必须返回错误，却成功了")
223		}
224		if errors.Is(err, ErrNotFound) {
225			t.Fatalf("目标版本确实存在，不应返回 ErrNotFound，得到 %v", err)
226		}
227	
228		got, err := s.GetBatch("B1")
229		if err != nil {
230			t.Fatalf("失败后查询批次失败: %v", err)
231		}
232		// 批次保持在上一次成功状态（R9/v1、1 份、草稿），而不是半改成 2 份。
233		if got.RecipeNo != "R9" || got.RecipeVersion != "v1" || got.PlannedPortions != 1 || got.Status != StatusDraft {
234			t.Fatalf("溢出失败不应改动份数或配方，得到 配方=%q/%q 份数=%d 状态=%s",
235				got.RecipeNo, got.RecipeVersion, got.PlannedPortions, got.Status)
236		}
237		// 数量核对仍为一份的完整结果：两种物料都在，Mbig 是上限原值而非回绕后的数。
238		mats := materialsMap(got)
239		if len(mats) != 2 {
240			t.Fatalf("不能只保留部分物料，应仍有 2 项，得到 %d 项: %+v", len(mats), mats)
241		}
242		checkRequirement(t, mats, "Mbig", "9223372036854775.807", "0", "-9223372036854775.807")
243		checkRequirement(t, mats, "M2", "1", "0", "-1")
244	
245		// 从原基础批次直接切到上限配方 × 2 份，同样必须整体回滚。
246		if _, err := s.UpdateDraftBatch("u-reset", "B1", "R1", "v1", 10); err != nil {
247			t.Fatalf("切回基础配方应成功: %v", err)
248		}
249		if _, err := s.UpdateDraftBatch("u-over", "B1", "R9", "v1", 2); err == nil {
250			t.Fatal("切到上限配方并改为 2 份应失败，却成功了")
251		}
252		got2, err := s.GetBatch("B1")
253		if err != nil {
254			t.Fatalf("失败后查询批次失败: %v", err)
255		}
256		if got2.RecipeNo != "R1" || got2.RecipeVersion != "v1" || got2.PlannedPortions != 10 {
257			t.Fatalf("失败后应完整保留调整前批次，得到 %+v", got2)
258		}
259		mats2 := materialsMap(got2)
260		if len(mats2) != 1 {
261			t.Fatalf("应只保留原配方 M1，得到 %d 项: %+v", len(mats2), mats2)
262		}
263		checkRequirement(t, mats2, "M1", "1000", "0", "-1000")
264	}
265	
266	// 失败的调整不占用请求编号：用同一编号修正为有效的版本与份数后应成功，
267	// 查询只显示这次成功调整的完整结果。
268	func TestUpdateDraftFailureDoesNotConsumeRequestNo(t *testing.T) {
269		s := openTestStore(t)
270		registerTwoRecipeVersions(t, s)
271		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
272			t.Fatal(err)
273		}
274	
275		// 同一编号先以不存在的版本提交（失败），再以有效版本与份数提交（成功）。
276		if _, err := s.UpdateDraftBatch("u-fix", "B1", "R1", "v9", 5); !errors.Is(err, ErrNotFound) {
277			t.Fatalf("不存在的版本应返回 ErrNotFound，得到 %v", err)
278		}
279		view, err := s.UpdateDraftBatch("u-fix", "B1", "R1", "v2", 4)
280		if err != nil {
281			t.Fatalf("失败不应占用请求编号，修正后应成功: %v", err)
282		}
283		if view.RecipeVersion != "v2" || view.PlannedPortions != 4 {
284			t.Fatalf("成功结果应指向有效调整: %+v", view)
285		}
286	
287		got, err := s.GetBatch("B1")
288		if err != nil {
289			t.Fatal(err)
290		}
291		if got.RecipeVersion != "v2" || got.PlannedPortions != 4 || got.Status != StatusDraft {
292			t.Fatalf("查询应只反映成功的调整: %+v", got)
293		}
294		mats := materialsMap(got)
295		if len(mats) != 2 {
296			t.Fatalf("应只含新版本 2 种物料，得到 %d 项", len(mats))
297		}
298		checkRequirement(t, mats, "M1", "1000", "0", "-1000") // 250 × 4
299		checkRequirement(t, mats, "M4", "8", "0", "-8")       // 2 × 4
300	
301		// 溢出失败同样不占用编号：换用新编号先失败，再用同一编号改成可计算的一份。
302		if _, err := s.RegisterRecipe("recipe-ov", "R9", "v1", "上限配方", []MaterialInput{
303			{MaterialNo: "Mbig", Grams: "9223372036854775.807"},
304		}); err != nil {
305			t.Fatalf("登记上限配方失败: %v", err)
306		}
307		if _, err := s.UpdateDraftBatch("u-fix2", "B1", "R9", "v1", 2); err == nil {
308			t.Fatal("两份溢出应失败，却成功了")
309		}
310		view2, err := s.UpdateDraftBatch("u-fix2", "B1", "R9", "v1", 1)
311		if err != nil {
312			t.Fatalf("溢出失败不应占用请求编号，修正为一份后应成功: %v", err)
313		}
314		if view2.PlannedPortions != 1 || view2.RecipeVersion != "v1" || view2.RecipeNo != "R9" {
315			t.Fatalf("修正后的成功结果不正确: %+v", view2)
316		}
317	}
318	
319	// 保留局部调整的合法语义：配方编号与版本号都留空表示不改配方，
320	// 份数传 0 表示不改份数；这些调用不能被当成缺项拒绝。
321	// 同时确认开始执行后不能借组合调用重新调整计划。
322	func TestUpdateDraftPartialAdjustmentsStillValid(t *testing.T) {
323		s := openTestStore(t)
324		registerTwoRecipeVersions(t, s)
325		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
326			t.Fatal(err)
327		}
328	
329		// 只改份数，配方不动。
330		v1, err := s.UpdateDraftBatch("u-p", "B1", "", "", 20)
331		if err != nil {
332			t.Fatalf("配方留空应表示不改配方: %v", err)
333		}
334		if v1.RecipeNo != "R1" || v1.RecipeVersion != "v1" || v1.PlannedPortions != 20 {
335			t.Fatalf("只改份数的结果不正确: %+v", v1)
336		}
337		// 只改配方，份数传 0 不动份数。
338		v2, err := s.UpdateDraftBatch("u-r", "B1", "R1", "v2", 0)
339		if err != nil {
340			t.Fatalf("份数传 0 应表示不改份数: %v", err)
341		}
342		if v2.RecipeNo != "R1" || v2.RecipeVersion != "v2" || v2.PlannedPortions != 20 {
343			t.Fatalf("只改配方的结果不正确: %+v", v2)
344		}
345		// 两者都缺省：合法的无变化调用，原样返回。
346		v3, err := s.UpdateDraftBatch("u-nop", "B1", "", "", 0)
347		if err != nil {
348			t.Fatalf("配方与份数都缺省应为合法的无变化调整: %v", err)
349		}
350		if v3.RecipeVersion != "v2" || v3.PlannedPortions != 20 || v3.Status != StatusDraft {
351			t.Fatalf("无变化调整结果不正确: %+v", v3)
352		}
353	
354		// 开始执行后，组合调整同样不被允许。
355		if _, err := s.StartBatch("s1", "B1"); err != nil {
356			t.Fatal(err)
357		}
358		if _, err := s.UpdateDraftBatch("u-after", "B1", "R1", "v1", 30); !errors.Is(err, ErrInvalidState) {
359			t.Fatalf("执行后组合调整应返回 ErrInvalidState，得到 %v", err)
360		}
361		got, err := s.GetBatch("B1")
362		if err != nil {
363			t.Fatal(err)
364		}
365		if got.RecipeVersion != "v2" || got.PlannedPortions != 20 || got.Status != StatusExecuting {
366			t.Fatalf("执行后的非法调整不应改动批次: %+v", got)
367		}
368	}
